_sage_const_5 = Integer(5); _sage_const_4 = Integer(4); _sage_const_1 = Integer(1); _sage_const_2 = Integer(2); _sage_const_0 = Integer(0); _sage_const_0p0 = RealNumber('0.0'); _sage_const_0p035 = RealNumber('0.035'); _sage_const_0p010 = RealNumber('0.010'); _sage_const_0p020 = RealNumber('0.020'); _sage_const_0p015 = RealNumber('0.015'); _sage_const_0p025 = RealNumber('0.025'); _sage_const_0p030 = RealNumber('0.030'); _sage_const_0p005 = RealNumber('0.005')# -----------------------------------------------------------------------------
# boost_mlwe_full_test.sage
#
# End-to-end correctness test for the Boost-MLWE idea:
#
#   CLIENT (smallest representation)
#       rank 1, ring degree n = POLDEG, one modulus q0
#           |
#           |  genuine key-switch / rank-up (NOT zero padding)
#           v
#   SERVER
#       MLWE rank r = MLWE, same ring degree n, still at q0
#           |
#           |  HEAANBOOT-style ModHE bootstrap
#           v
#       MLWE rank r, post-bootstrap evaluation modulus Q_eval
#
# The base/evaluation q-primes are the q_list entries already present in
# constants.sage. configure_heaanboot_chain() appends temporary bootstrap primes
