direct_dec = hb_decrypt_slots(ct_direct_boot, key_eval)
direct_boot_err = _max_slot_error(direct_dec, vals)

print("direct rank-r bootstrap max abs error =", direct_boot_err)
print("Boost-MLWE bootstrap max abs error    =", boot_err)
print("extra error from rank-up path (rough) =", max(_sage_const_0p0 , boot_err - direct_boot_err))


# =============================================================================
# 8. POST-BOOTSTRAP USABILITY: one MLWE multiplication
# =============================================================================

print("\n================================================")
print("STAGE D: ONE POST-BOOTSTRAP MLWE SQUARE")
